HTML_CODE = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Gemini Strategic Arsenal 3D - \uc2e4\uc2dc\uac04 \ud0c4\ub3c4/\ud575\ud3ed\ubc1c \uc2dc\ubbac\ub808\uc774\ud130</title>\n<style>\n  * { box-sizing: border-box; margin: 0; padding: 0; user-select: none; }\n  html, body {\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n    background: #070b12;\n    font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n    color: #e6edf3;\n  }\n  #canvas-container {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n  }\n  /* Thermal Flash Overlay */\n  #flash-overlay {\n    position: absolute;\n    inset: 0;\n    background: radial-gradient(circle, #ffffff 0%, #fff4d2 45%, #ff9d3b 100%);\n    opacity: 0;\n    pointer-events: none;\n    z-index: 30;\n    transition: opacity 0.05s linear;\n  }\n  /* Top Telemetry Bar */\n  #top-hud {\n    position: absolute;\n    top: 12px;\n    left: 50%;\n    transform: translateX(-50%);\n    display: flex;\n    align-items: center;\n    gap: 18px;\n    background: rgba(13, 17, 23, 0.85);\n    backdrop-filter: blur(10px);\n    border: 1px solid rgba(255, 255, 255, 0.14);\n    border-radius: 12px;\n    padding: 8px 20px;\n    z-index: 20;\n    box-shadow: 0 8px 24px rgba(0,0,0,0.5);\n  }\n  .tele-item { text-align: center; min-width: 82px; }\n  .tele-label { font-size: 10px; color: #8b949e; letter-spacing: 0.8px; text-transform: uppercase; }\n  .tele-val { font-size: 15px; font-weight: 800; font-variant-numeric: tabular-nums; margin-top: 2px; }\n  .status-ready { color: #58a6ff; }\n  .status-flight { color: #f0883e; }\n  .status-detonated { color: #ff4b4b; }\n\n  /* Left Control Panel */\n  #left-panel {\n    position: absolute;\n    top: 12px;\n    left: 12px;\n    width: 285px;\n    max-height: calc(100vh - 86px);\n    overflow-y: auto;\n    background: rgba(13, 17, 23, 0.88);\n    backdrop-filter: blur(12px);\n    border: 1px solid rgba(255, 255, 255, 0.14);\n    border-radius: 12px;\n    padding: 14px;\n    z-index: 20;\n    box-shadow: 0 8px 28px rgba(0,0,0,0.55);\n  }\n  #left-panel::-webkit-scrollbar { width: 5px; }\n  #left-panel::-webkit-scrollbar-thumb { background: #30363d; border-radius: 4px; }\n\n  .panel-title {\n    font-size: 15px;\n    font-weight: 800;\n    color: #fff;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    margin-bottom: 10px;\n    padding-bottom: 8px;\n    border-bottom: 1px solid #21262d;\n  }\n  .section-lbl {\n    font-size: 11px;\n    font-weight: 700;\n    color: #8b949e;\n    margin: 10px 0 5px 0;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n  }\n  select, input[type=\"range\"] {\n    width: 100%;\n    background: #161b22;\n    color: #e6edf3;\n    border: 1px solid #30363d;\n    border-radius: 7px;\n    padding: 6px 8px;\n    font-size: 12px;\n    outline: none;\n  }\n  select:focus { border-color: #58a6ff; }\n  input[type=\"range\"] { padding: 0; accent-color: #ff4b4b; cursor: pointer; }\n\n  .row-between {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    font-size: 12px;\n    margin-bottom: 4px;\n  }\n  .badge-val {\n    background: #21262d;\n    padding: 2px 7px;\n    border-radius: 5px;\n    font-weight: 700;\n    color: #ffa657;\n    font-size: 11px;\n  }\n\n  .btn-group {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 6px;\n    margin-top: 4px;\n  }\n  .btn-toggle {\n    background: #161b22;\n    border: 1px solid #30363d;\n    color: #8b949e;\n    padding: 6px 4px;\n    border-radius: 7px;\n    font-size: 11px;\n    font-weight: 700;\n    cursor: pointer;\n    text-align: center;\n    transition: all 0.15s;\n  }\n  .btn-toggle.active {\n    background: rgba(88, 166, 255, 0.18);\n    border-color: #58a6ff;\n    color: #fff;\n  }\n\n  #launch-btn {\n    width: 100%;\n    margin-top: 12px;\n    padding: 11px;\n    border: none;\n    border-radius: 9px;\n    background: linear-gradient(135deg, #ff3b30 0%, #d9261c 100%);\n    color: #fff;\n    font-size: 14px;\n    font-weight: 800;\n    letter-spacing: 0.5px;\n    cursor: pointer;\n    box-shadow: 0 4px 16px rgba(255, 59, 48, 0.45);\n    transition: transform 0.1s, filter 0.15s;\n  }\n  #launch-btn:hover { filter: brightness(1.1); }\n  #launch-btn:active { transform: scale(0.98); }\n\n  .sub-actions {\n    display: grid;\n    grid-template-columns: 1fr 1fr 1fr;\n    gap: 5px;\n    margin-top: 6px;\n  }\n  .btn-sub {\n    background: #21262d;\n    border: 1px solid #30363d;\n    color: #c9d1d9;\n    padding: 6px 4px;\n    border-radius: 7px;\n    font-size: 11px;\n    font-weight: 600;\n    cursor: pointer;\n  }\n  .btn-sub:hover { background: #30363d; }\n\n  /* Right Damage & Casualty Panel */\n  #right-panel {\n    position: absolute;\n    top: 12px;\n    right: 12px;\n    width: 255px;\n    background: rgba(13, 17, 23, 0.88);\n    backdrop-filter: blur(12px);\n    border: 1px solid rgba(255, 255, 255, 0.14);\n    border-radius: 12px;\n    padding: 14px;\n    z-index: 20;\n    box-shadow: 0 8px 28px rgba(0,0,0,0.55);\n  }\n  .stat-card {\n    background: #161b22;\n    border: 1px solid #282e36;\n    border-radius: 9px;\n    padding: 9px 11px;\n    margin-bottom: 8px;\n  }\n  .stat-lbl { font-size: 11px; color: #8b949e; font-weight: 600; }\n  .stat-num-red { font-size: 21px; font-weight: 800; color: #ff4b4b; margin-top: 2px; font-variant-numeric: tabular-nums; }\n  .stat-num-org { font-size: 19px; font-weight: 800; color: #ffa657; margin-top: 2px; font-variant-numeric: tabular-nums; }\n\n  .zone-list { margin-top: 6px; }\n  .zone-item {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    font-size: 11.5px;\n    padding: 5px 0;\n    border-bottom: 1px solid #21262d;\n  }\n  .zone-item:last-child { border-bottom: none; }\n  .dot {\n    display: inline-block;\n    width: 9px;\n    height: 9px;\n    border-radius: 50%;\n    margin-right: 6px;\n  }\n\n  /* Bottom Timeline Bar */\n  #bottom-bar {\n    position: absolute;\n    bottom: 12px;\n    left: 50%;\n    transform: translateX(-50%);\n    width: min(740px, calc(100% - 24px));\n    background: rgba(13, 17, 23, 0.9);\n    backdrop-filter: blur(12px);\n    border: 1px solid rgba(255, 255, 255, 0.15);\n    border-radius: 12px;\n    padding: 9px 16px;\n    z-index: 20;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n  }\n  #timeline-slider { flex: 1; accent-color: #58a6ff; }\n  .cam-pills { display: flex; gap: 4px; }\n  .cam-pill {\n    background: #161b22;\n    border: 1px solid #30363d;\n    color: #8b949e;\n    border-radius: 6px;\n    padding: 4px 8px;\n    font-size: 11px;\n    font-weight: 700;\n    cursor: pointer;\n    white-space: nowrap;\n  }\n  .cam-pill.active { background: #1f6feb; border-color: #58a6ff; color: #fff; }\n</style>\n</head>\n<body>\n\n<div id=\"canvas-container\"></div>\n<div id=\"flash-overlay\"></div>\n\n<!-- Top Telemetry HUD -->\n<div id=\"top-hud\">\n  <div class=\"tele-item\">\n    <div class=\"tele-label\">\uc791\uc804 \uc0c1\ud0dc</div>\n    <div id=\"hud-status\" class=\"tele-val status-ready\">\ubc1c\uc0ac \ub300\uae30</div>\n  </div>\n  <div class=\"tele-item\">\n    <div class=\"tele-label\">\uacbd\uacfc \uc2dc\uac04</div>\n    <div id=\"hud-time\" class=\"tele-val\">T+ 00.0s</div>\n  </div>\n  <div class=\"tele-item\">\n    <div class=\"tele-label\">\ud0c4\ub450 \uace0\ub3c4</div>\n    <div id=\"hud-alt\" class=\"tele-val\">0.0 km</div>\n  </div>\n  <div class=\"tele-item\">\n    <div class=\"tele-label\">\ube44\ud589 \uc18d\ub3c4</div>\n    <div id=\"hud-speed\" class=\"tele-val\">Mach 0.0</div>\n  </div>\n  <div class=\"tele-item\">\n    <div class=\"tele-label\">\ubc84\uc12f\uad6c\ub984 \uace0\ub3c4</div>\n    <div id=\"hud-cloud\" class=\"tele-val\">0.0 km</div>\n  </div>\n</div>\n\n<!-- Left Control Panel -->\n<div id=\"left-panel\">\n  <div class=\"panel-title\">\u2622\ufe0f Strategic Arsenal 3D</div>\n\n  <div class=\"section-lbl\">1. \ud0c0\uaca9 \ubaa9\ud45c \ub3c4\uc2dc</div>\n  <select id=\"target-select\">\n    <option value=\"seoul\" selected>\ud83c\uddf0\ud83c\uddf7 \uc11c\uc6b8 \uccad\uacc4\uad11\uc7a5 (\ub3c4\uc2ec \ubc00\uc9d1)</option>\n    <option value=\"pyongyang\">\ud83c\uddf0\ud83c\uddf5 \ud3c9\uc591 \uae40\uc77c\uc131\uad11\uc7a5</option>\n    <option value=\"tokyo\">\ud83c\uddef\ud83c\uddf5 \ub3c4\ucfc4 \uc2e0\uc8fc\ucfe0</option>\n    <option value=\"beijing\">\ud83c\udde8\ud83c\uddf3 \ubca0\uc774\uc9d5 \ud188\uc548\uba3c</option>\n    <option value=\"washington\">\ud83c\uddfa\ud83c\uddf8 \uc6cc\uc2f1\ud134 D.C.</option>\n  </select>\n\n  <div class=\"section-lbl\">2. \ud0c4\ub450 / \ubb34\uae30 \uccb4\uacc4</div>\n  <select id=\"weapon-select\">\n    <option value=\"15\">Little Boy (\ud788\ub85c\uc2dc\ub9c8 \uc6d0\ud3ed - 15 kt)</option>\n    <option value=\"50\" selected>B61-12 (\ubbf8\uad6d \ucd5c\uc2e0 \uc804\uc220\ud575 - 50 kt)</option>\n    <option value=\"300\">W87 (\ubbf8\ub2c8\ud2b8\ub9e8 III ICBM - 300 kt)</option>\n    <option value=\"1500\">\ud654\uc131-17\ud615 (ICBM \ucd94\uc815\uce58 - 1,500 kt)</option>\n    <option value=\"5000\">RS-28 \uc0ac\ub974\ub9db (\ub7ec\uc2dc\uc544 ICBM - 5,000 kt)</option>\n    <option value=\"50000\">Tsar Bomba (\uc5ed\ub300 \ucd5c\ub300 \uc2e4\ud5d8\ud575 - 50,000 kt)</option>\n    <option value=\"custom\">\uc9c1\uc811 \uc704\ub825 \uc870\uc808 (Custom)</option>\n  </select>\n\n  <div style=\"margin-top:8px;\">\n    <div class=\"row-between\">\n      <span>\ud3ed\ubc1c \uc704\ub825 (Yield)</span>\n      <span id=\"yield-badge\" class=\"badge-val\">50 kt</span>\n    </div>\n    <input type=\"range\" id=\"yield-slider\" min=\"1\" max=\"100\" value=\"35\" />\n  </div>\n\n  <div class=\"section-lbl\">3. \ud3ed\ubc1c \uace0\ub3c4 & \uc9c0\ub3c4 \uc2a4\ud0c0\uc77c</div>\n  <div class=\"btn-group\">\n    <div id=\"btn-ground\" class=\"btn-toggle active\">\uc9c0\ud45c\uba74 \ud3ed\ubc1c</div>\n    <div id=\"btn-air\" class=\"btn-toggle\">\uacf5\uc911 \ud3ed\ubc1c (+30%)</div>\n  </div>\n  <div class=\"btn-group\" style=\"margin-top:5px;\">\n    <div id=\"btn-map-dark\" class=\"btn-toggle active\">\uc804\uc220 \ub2e4\ud06c\ub9f5</div>\n    <div id=\"btn-map-sat\" class=\"btn-toggle\">\uc704\uc131 \uc2e4\uc0ac\ub9f5</div>\n  </div>\n\n  <div class=\"section-lbl\">4. \uae30\uc0c1 (\ud48d\ud5a5 / \ud48d\uc18d)</div>\n  <div class=\"row-between\">\n    <span>\ud48d\ud5a5 (\ub099\uc9c4 \ud655\uc0b0 \ubc29\ud5a5)</span>\n    <span id=\"wind-deg-badge\" class=\"badge-val\">90\u00b0 (\ub3d9\ucabd)</span>\n  </div>\n  <input type=\"range\" id=\"wind-deg\" min=\"0\" max=\"360\" value=\"90\" />\n\n  <div class=\"row-between\" style=\"margin-top:6px;\">\n    <span>\ud48d\uc18d</span>\n    <span id=\"wind-spd-badge\" class=\"badge-val\">30 km/h</span>\n  </div>\n  <input type=\"range\" id=\"wind-spd\" min=\"0\" max=\"100\" value=\"30\" />\n\n  <button id=\"launch-btn\">\ud83d\ude80 \ubbf8\uc0ac\uc77c \ubc1c\uc0ac (LAUNCH)</button>\n  <div class=\"sub-actions\">\n    <button id=\"pause-btn\" class=\"btn-sub\">\u23f8 \uc77c\uc2dc\uc815\uc9c0</button>\n    <button id=\"reset-btn\" class=\"btn-sub\">\ud83d\udd04 \ucd08\uae30\ud654</button>\n    <button id=\"sound-btn\" class=\"btn-sub\">\ud83d\udd0a \ud6a8\uacfc\uc74c ON</button>\n  </div>\n</div>\n\n<!-- Right Live Casualty & Radius Panel -->\n<div id=\"right-panel\">\n  <div class=\"panel-title\">\ud83d\udcca \uc2e4\uc2dc\uac04 \ud53c\ud574 \ubd84\uc11d</div>\n  <div class=\"stat-card\">\n    <div class=\"stat-lbl\">\ub204\uc801 \ucd94\uc815 \uc0ac\ub9dd\uc790 (\uc2e4\uc2dc\uac04 \uc5f0\uc0b0)</div>\n    <div id=\"stat-dead\" class=\"stat-num-red\">0 \uba85</div>\n  </div>\n  <div class=\"stat-card\">\n    <div class=\"stat-lbl\">\ub204\uc801 \ucd94\uc815 \ubd80\uc0c1\uc790</div>\n    <div id=\"stat-injured\" class=\"stat-num-org\">0 \uba85</div>\n  </div>\n\n  <div class=\"section-lbl\">\uad6c\uc5ed\ubcc4 \ucd5c\ub300 \ud53c\ud574 \ubc18\uacbd</div>\n  <div class=\"zone-list\">\n    <div class=\"zone-item\">\n      <span><i class=\"dot\" style=\"background:#ff2a2a;\"></i>\ud654\uad6c (\uc989\uac01 \uae30\ud654)</span>\n      <strong id=\"rad-fireball\">0.52 km</strong>\n    </div>\n    <div class=\"zone-item\">\n      <span><i class=\"dot\" style=\"background:#ff6b00;\"></i>20 psi (\ucf58\ud06c\ub9ac\ud2b8 \uc644\ud30c)</span>\n      <strong id=\"rad-20psi\">1.02 km</strong>\n    </div>\n    <div class=\"zone-item\">\n      <span><i class=\"dot\" style=\"background:#ffd000;\"></i>5 psi (\uc77c\ubc18\uac74\ubb3c \ubd95\uad34)</span>\n      <strong id=\"rad-5psi\">2.55 km</strong>\n    </div>\n    <div class=\"zone-item\">\n      <span><i class=\"dot\" style=\"background:#ff9e44;\"></i>\uc5f4\ubcf5\uc0ac (3\ub3c4 \ud654\uc0c1)</span>\n      <strong id=\"rad-thermal\">5.74 km</strong>\n    </div>\n    <div class=\"zone-item\">\n      <span><i class=\"dot\" style=\"background:#b44cff;\"></i>\ubc29\uc0ac\ub2a5 \ub099\uc9c4 (Fallout)</span>\n      <strong id=\"rad-fallout\">18.4 km</strong>\n    </div>\n  </div>\n  <div style=\"margin-top:8px; font-size:10.5px; color:#8b949e; line-height:1.4;\">\n    \ud83d\udca1 \ub9c8\uc6b0\uc2a4 \uc88c\ud074\ub9ad \ud68c\uc804, \uc6b0\ud074\ub9ad \uc774\ub3d9, \ud720 \ud655\ub300/\ucd95\uc18c \uc9c0\uc6d0\n  </div>\n</div>\n\n<!-- Bottom Timeline & Camera Bar -->\n<div id=\"bottom-bar\">\n  <span style=\"font-size:11px; font-weight:700; color:#8b949e; white-space:nowrap;\">\uc2dc\ud000\uc2a4 \uc81c\uc5b4</span>\n  <input type=\"range\" id=\"timeline-slider\" min=\"0\" max=\"1000\" value=\"0\" />\n  <div class=\"cam-pills\">\n    <div class=\"cam-pill active\" data-cam=\"auto\">\ud83c\udfa5 \uc790\ub3d9\uc5f0\ucd9c</div>\n    <div class=\"cam-pill\" data-cam=\"missile\">\ud83d\ude80 \ud0c4\ub450\ucd94\uc801</div>\n    <div class=\"cam-pill\" data-cam=\"ground\">\ud83c\udfd9\ufe0f \uc9c0\uc0c1\uc2dc\uc810</div>\n    <div class=\"cam-pill\" data-cam=\"orbit\">\ud83d\udef0\ufe0f \uc790\uc720\uc2dc\uc810</div>\n  </div>\n</div>\n\n<!-- Three.js & OrbitControls from reliable CDN -->\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js\"></script>\n\n<script>\n// =========================================================\n// 1. CITY & WEAPON CONFIGURATION DATA\n// =========================================================\nconst CITIES = {\n  seoul:      { name: \"\uc11c\uc6b8 \uccad\uacc4\uad11\uc7a5\", lat: 37.5693, lon: 126.9774, popCap: 9800000, density: 16000, riverAngle: 0.12 },\n  pyongyang:  { name: \"\ud3c9\uc591 \uae40\uc77c\uc131\uad11\uc7a5\", lat: 39.0194, lon: 125.7533, popCap: 3100000, density: 9500,  riverAngle: -0.45 },\n  tokyo:      { name: \"\ub3c4\ucfc4 \uc2e0\uc8fc\ucfe0\",   lat: 35.6909, lon: 139.7002, popCap: 14000000, density: 15500, riverAngle: 0.6 },\n  beijing:    { name: \"\ubca0\uc774\uc9d5 \ud188\uc548\uba3c\", lat: 39.9042, lon: 116.3975, popCap: 12500000, density: 11500, riverAngle: 0.0 },\n  washington: { name: \"\uc6cc\uc2f1\ud134 D.C.\",   lat: 38.8951, lon: -77.0364, popCap: 2800000, density: 4800,  riverAngle: -0.7 }\n};\n\nlet state = {\n  cityKey: \"seoul\",\n  yieldKt: 50,\n  burstType: \"ground\", // 'ground' or 'air'\n  mapStyle: \"dark\",    // 'dark' or 'sat'\n  windDeg: 90,\n  windSpeed: 30,\n  cameraMode: \"auto\",\n  soundEnabled: true,\n\n  // Timeline state: 0.0 -> 1.0 (0~0.32 missile flight, 0.32 detonation, 0.32~1.0 explosion & mushroom cloud)\n  phase: \"ready\", // 'ready', 'playing', 'paused', 'finished'\n  progress: 0.0,\n  totalDuration: 18.0, // seconds\n  impactPoint: 0.30,   // normalized time of impact\n  flashTriggered: false\n};\n\n// Logarithmic slider mapping (1 kt -> 50,000 kt)\nfunction sliderToYield(v) {\n  const minLog = Math.log(1);\n  const maxLog = Math.log(50000);\n  const val = Math.exp(minLog + (maxLog - minLog) * ((v - 1) / 99));\n  return val < 10 ? Math.round(val * 10) / 10 : Math.round(val);\n}\nfunction yieldToSlider(y) {\n  const minLog = Math.log(1);\n  const maxLog = Math.log(50000);\n  return Math.round(1 + 99 * ((Math.log(Math.max(1, y)) - minLog) / (maxLog - minLog)));\n}\n\n// =========================================================\n// 2. WEB AUDIO API SOUND SYNTHESIZER (NO EXTERNAL FILES)\n// =========================================================\nlet audioCtx = null;\nfunction initAudio() {\n  if (!audioCtx) {\n    const AudioContext = window.AudioContext || window.webkitAudioContext;\n    if (AudioContext) audioCtx = new AudioContext();\n  }\n  if (audioCtx && audioCtx.state === \"suspended\") audioCtx.resume();\n}\n\nfunction playLaunchSound() {\n  if (!state.soundEnabled) return;\n  initAudio();\n  if (!audioCtx) return;\n\n  const now = audioCtx.currentTime;\n  // Rocket thrust noise\n  const bufferSize = audioCtx.sampleRate * 3.5;\n  const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);\n  const data = buffer.getChannelData(0);\n  for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (audioCtx.sampleRate * 1.8));\n\n  const noise = audioCtx.createBufferSource();\n  noise.buffer = buffer;\n\n  const filter = audioCtx.createBiquadFilter();\n  filter.type = \"bandpass\";\n  filter.frequency.setValueAtTime(220, now);\n  filter.frequency.exponentialRampToValueAtTime(950, now + 1.5);\n  filter.frequency.exponentialRampToValueAtTime(160, now + 3.4);\n\n  const gain = audioCtx.createGain();\n  gain.gain.setValueAtTime(0.01, now);\n  gain.gain.linearRampToValueAtTime(0.22, now + 0.3);\n  gain.gain.exponentialRampToValueAtTime(0.001, now + 3.4);\n\n  noise.connect(filter);\n  filter.connect(gain);\n  gain.connect(audioCtx.destination);\n  noise.start(now);\n}\n\nfunction playExplosionSound() {\n  if (!state.soundEnabled) return;\n  initAudio();\n  if (!audioCtx) return;\n\n  const now = audioCtx.currentTime;\n  // 1. Sub-bass shockwave boom\n  const osc = audioCtx.createOscillator();\n  const oscGain = audioCtx.createGain();\n  osc.type = \"sine\";\n  osc.frequency.setValueAtTime(95, now);\n  osc.frequency.exponentialRampToValueAtTime(22, now + 3.2);\n  oscGain.gain.setValueAtTime(0.75, now);\n  oscGain.gain.exponentialRampToValueAtTime(0.001, now + 3.5);\n  osc.connect(oscGain);\n  oscGain.connect(audioCtx.destination);\n  osc.start(now);\n  osc.stop(now + 3.6);\n\n  // 2. Thunderous blast crackle & rumble\n  const dur = 5.5;\n  const bufferSize = audioCtx.sampleRate * dur;\n  const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);\n  const data = buffer.getChannelData(0);\n  for (let i = 0; i < bufferSize; i++) {\n    const env = Math.exp(-i / (audioCtx.sampleRate * 1.4));\n    data[i] = (Math.random() * 2 - 1) * env;\n  }\n  const noise = audioCtx.createBufferSource();\n  noise.buffer = buffer;\n\n  const lowpass = audioCtx.createBiquadFilter();\n  lowpass.type = \"lowpass\";\n  lowpass.frequency.setValueAtTime(1400, now);\n  lowpass.frequency.exponentialRampToValueAtTime(95, now + dur);\n\n  const nGain = audioCtx.createGain();\n  nGain.gain.setValueAtTime(0.65, now);\n  nGain.gain.exponentialRampToValueAtTime(0.001, now + dur);\n\n  noise.connect(lowpass);\n  lowpass.connect(nGain);\n  nGain.connect(audioCtx.destination);\n  noise.start(now);\n}\n\n// =========================================================\n// 3. THREE.JS 3D ENGINE INITIALIZATION\n// =========================================================\nconst container = document.getElementById(\"canvas-container\");\nconst scene = new THREE.Scene();\nscene.background = new THREE.Color(0x070b12);\nscene.fog = new THREE.FogExp2(0x070b12, 0.0011);\n\nconst camera = new THREE.PerspectiveCamera(48, window.innerWidth / window.innerHeight, 0.5, 4000);\ncamera.position.set(0, 145, 220);\n\nconst renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: \"high-performance\" });\nrenderer.setSize(window.innerWidth, window.innerHeight);\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\ncontainer.appendChild(renderer.domElement);\n\nconst controls = new THREE.OrbitControls(camera, renderer.domElement);\ncontrols.enableDamping = true;\ncontrols.dampingFactor = 0.06;\ncontrols.maxPolarAngle = Math.PI * 0.485;\ncontrols.minDistance = 18;\ncontrols.maxDistance = 950;\ncontrols.target.set(0, 10, 0);\n\n// Lighting\nconst ambientLight = new THREE.AmbientLight(0x6c7a89, 1.15);\nscene.add(ambientLight);\n\nconst dirLight = new THREE.DirectionalLight(0xdce8f5, 1.1);\ndirLight.position.set(160, 280, 140);\nscene.add(dirLight);\n\nconst blastLight = new THREE.PointLight(0xff8822, 0, 900);\nblastLight.position.set(0, 18, 0);\nscene.add(blastLight);\n\n// =========================================================\n// 4. MAP GROUND TEXTURE (PROCEDURAL + REAL TILE OVERLAY)\n// =========================================================\n// World scale: 1 scene unit = 100 meters (so 600 units = 60 km x 60 km map)\nconst WORLD_SIZE = 700; // 70 km\nconst METERS_PER_UNIT = 100;\n\nconst mapCanvas = document.createElement(\"canvas\");\nmapCanvas.width = 1024;\nmapCanvas.height = 1024;\nconst mapCtx = mapCanvas.getContext(\"2d\");\nconst groundTexture = new THREE.CanvasTexture(mapCanvas);\ngroundTexture.anisotropy = 8;\n\nfunction drawProceduralBaseMap() {\n  const isSat = state.mapStyle === \"sat\";\n  mapCtx.fillStyle = isSat ? \"#1c261e\" : \"#0c121c\";\n  mapCtx.fillRect(0, 0, 1024, 1024);\n\n  // Subtle city road blocks\n  mapCtx.strokeStyle = isSat ? \"rgba(180,185,170,0.18)\" : \"rgba(56, 139, 253, 0.14)\";\n  mapCtx.lineWidth = 1;\n  for (let i = 0; i <= 1024; i += 32) {\n    mapCtx.beginPath(); mapCtx.moveTo(i, 0); mapCtx.lineTo(i, 1024); mapCtx.stroke();\n    mapCtx.beginPath(); mapCtx.moveTo(0, i); mapCtx.lineTo(1024, i); mapCtx.stroke();\n  }\n\n  // Major arterial highways\n  mapCtx.strokeStyle = isSat ? \"rgba(220,210,180,0.32)\" : \"rgba(88, 166, 255, 0.28)\";\n  mapCtx.lineWidth = 2.5;\n  for (let i = 128; i < 1024; i += 192) {\n    mapCtx.beginPath(); mapCtx.moveTo(i, 0); mapCtx.lineTo(i, 1024); mapCtx.stroke();\n    mapCtx.beginPath(); mapCtx.moveTo(0, i); mapCtx.lineTo(1024, i); mapCtx.stroke();\n  }\n\n  // River feature (e.g. Han River / Taedong River)\n  const city = CITIES[state.cityKey];\n  mapCtx.save();\n  mapCtx.translate(512, 512);\n  mapCtx.rotate(city.riverAngle);\n  mapCtx.fillStyle = isSat ? \"#13293d\" : \"#09192b\";\n  mapCtx.beginPath();\n  mapCtx.moveTo(-600, 38);\n  mapCtx.bezierCurveTo(-200, 15, 200, 65, 600, 30);\n  mapCtx.lineTo(600, 72);\n  mapCtx.bezierCurveTo(200, 105, -200, 55, -600, 78);\n  mapCtx.closePath();\n  mapCtx.fill();\n  mapCtx.restore();\n\n  // Tactical range rings on ground\n  mapCtx.strokeStyle = isSat ? \"rgba(255,255,255,0.22)\" : \"rgba(88,166,255,0.25)\";\n  mapCtx.lineWidth = 1.5;\n  [100, 220, 350, 480].forEach(r => {\n    mapCtx.beginPath();\n    mapCtx.arc(512, 512, r, 0, Math.PI * 2);\n    mapCtx.stroke();\n  });\n\n  groundTexture.needsUpdate = true;\n}\n\nfunction loadRealMapTiles() {\n  drawProceduralBaseMap();\n  const city = CITIES[state.cityKey];\n  const zoom = 11; // ~76m/pixel -> 5x5 tiles covers ~95km around target\n  const n = Math.pow(2, zoom);\n  const centerX = Math.floor((city.lon + 180) / 360 * n);\n  const latRad = city.lat * Math.PI / 180;\n  const centerY = Math.floor((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2 * n);\n\n  const gridRadius = 2; // 5x5 grid\n  const tilePx = 1024 / (gridRadius * 2 + 1);\n\n  for (let dx = -gridRadius; dx <= gridRadius; dx++) {\n    for (let dy = -gridRadius; dy <= gridRadius; dy++) {\n      const tx = centerX + dx;\n      const ty = centerY + dy;\n      const url = state.mapStyle === \"sat\"\n        ? `https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/${zoom}/${ty}/${tx}`\n        : `https://basemaps.cartocdn.com/dark_all/${zoom}/${tx}/${ty}.png`;\n\n      const img = new Image();\n      img.crossOrigin = \"anonymous\";\n      img.onload = () => {\n        const px = (dx + gridRadius) * tilePx;\n        const py = (dy + gridRadius) * tilePx;\n        mapCtx.drawImage(img, px, py, tilePx + 0.5, tilePx + 0.5);\n        // Subtle tactical grid overlay on top of real map\n        mapCtx.strokeStyle = \"rgba(255,255,255,0.08)\";\n        mapCtx.lineWidth = 1;\n        mapCtx.strokeRect(px, py, tilePx, tilePx);\n        groundTexture.needsUpdate = true;\n      };\n      img.src = url;\n    }\n  }\n}\n\nconst groundGeo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE);\nconst groundMat = new THREE.MeshStandardMaterial({\n  map: groundTexture,\n  roughness: 0.9,\n  metalness: 0.1\n});\nconst groundMesh = new THREE.Mesh(groundGeo, groundMat);\ngroundMesh.rotation.x = -Math.PI / 2;\nscene.add(groundMesh);\n\n// =========================================================\n// 5. 3D CITY BUILDINGS (INSTANCED MESH THAT COLLAPSES ON BLAST)\n// =========================================================\nconst BUILDING_COUNT = 950;\nconst bldgGeo = new THREE.BoxGeometry(1, 1, 1);\nbldgGeo.translate(0, 0.5, 0); // pivot at ground\nconst bldgMat = new THREE.MeshStandardMaterial({ color: 0x8fa3b8, roughness: 0.65, metalness: 0.25 });\nconst cityInstanced = new THREE.InstancedMesh(bldgGeo, bldgMat, BUILDING_COUNT);\nscene.add(cityInstanced);\n\nconst buildings = [];\nconst dummy = new THREE.Object3D();\nconst bldgColor = new THREE.Color();\n\nfunction generateCityBuildings() {\n  buildings.length = 0;\n  for (let i = 0; i < BUILDING_COUNT; i++) {\n    // Cluster denser near ground zero (0,0) and spread outward\n    const angle = Math.random() * Math.PI * 2;\n    const dist = Math.pow(Math.random(), 0.72) * 195; // up to 19.5 km\n    const x = Math.cos(angle) * dist;\n    const z = Math.sin(angle) * dist;\n\n    // Height taller in downtown core\n    const coreFactor = Math.max(0.25, 1 - dist / 140);\n    const w = 1.2 + Math.random() * 2.2;\n    const d = 1.2 + Math.random() * 2.2;\n    const h = (1.5 + Math.random() * 9.5) * coreFactor + 1.0;\n\n    buildings.push({ x, z, w, d, h, dist, angle });\n  }\n  updateCityDestruction(0);\n}\n\nfunction updateCityDestruction(shockRadiusUnits, fireballRadiusUnits = 0, r20Units = 0, r5Units = 0) {\n  for (let i = 0; i < BUILDING_COUNT; i++) {\n    const b = buildings[i];\n    dummy.position.set(b.x, 0, b.z);\n\n    if (shockRadiusUnits <= 0 || b.dist > shockRadiusUnits) {\n      // Intact building\n      dummy.rotation.set(0, 0, 0);\n      dummy.scale.set(b.w, b.h, b.d);\n      bldgColor.setHex(b.dist < 35 ? 0x7b93ad : 0x56697d);\n    } else if (b.dist <= fireballRadiusUnits) {\n      // Vaporized completely\n      dummy.rotation.set(0, 0, 0);\n      dummy.scale.set(0.001, 0.001, 0.001);\n      bldgColor.setHex(0x111111);\n    } else if (b.dist <= r20Units) {\n      // Crushed rubble\n      const tiltDir = Math.atan2(b.x, b.z);\n      dummy.rotation.set(Math.cos(tiltDir) * 1.35, 0, -Math.sin(tiltDir) * 1.35);\n      dummy.scale.set(b.w * 1.2, b.h * 0.18, b.d * 1.2);\n      bldgColor.setHex(0x231d1b);\n    } else if (b.dist <= r5Units) {\n      // Heavily damaged / blown outward\n      const tiltDir = Math.atan2(b.x, b.z);\n      const tAmount = 0.45 + 0.45 * (1 - (b.dist - r20Units) / Math.max(1, r5Units - r20Units));\n      dummy.rotation.set(Math.cos(tiltDir) * tAmount, 0, -Math.sin(tiltDir) * tAmount);\n      dummy.scale.set(b.w, b.h * 0.65, b.d);\n      bldgColor.setHex(0x3a3230);\n    } else {\n      // Scorched by thermal wave\n      dummy.rotation.set(0, 0, 0);\n      dummy.scale.set(b.w, b.h, b.d);\n      bldgColor.setHex(0x493c36);\n    }\n\n    dummy.updateMatrix();\n    cityInstanced.setMatrixAt(i, dummy.matrix);\n    cityInstanced.setColorAt(i, bldgColor);\n  }\n  cityInstanced.instanceMatrix.needsUpdate = true;\n  if (cityInstanced.instanceColor) cityInstanced.instanceColor.needsUpdate = true;\n}\n\n// =========================================================\n// 6. TARGET RETICLE, LAUNCH PAD & BALLISTIC MISSILE\n// =========================================================\n// Pulsing Target Reticle at (0, 0.2, 0)\nconst reticleGroup = new THREE.Group();\nconst retRing1 = new THREE.Mesh(\n  new THREE.RingGeometry(3.5, 4.4, 48),\n  new THREE.MeshBasicMaterial({ color: 0xff3b30, side: THREE.DoubleSide, transparent: true, opacity: 0.9 })\n);\nretRing1.rotation.x = -Math.PI / 2;\nconst retRing2 = new THREE.Mesh(\n  new THREE.RingGeometry(7.5, 8.1, 48),\n  new THREE.MeshBasicMaterial({ color: 0xff3b30, side: THREE.DoubleSide, transparent: true, opacity: 0.45 })\n);\nretRing2.rotation.x = -Math.PI / 2;\nreticleGroup.add(retRing1, retRing2);\nreticleGroup.position.y = 0.3;\nscene.add(reticleGroup);\n\n// Ballistic Trajectory Curve (Launch from NW -> Target (0,0,0))\nconst launchOrigin = new THREE.Vector3(-190, 0, -170);\nconst midApex = new THREE.Vector3(-95, 165, -85);\nconst impactPos = new THREE.Vector3(0, 0, 0);\nconst missileCurve = new THREE.QuadraticBezierCurve3(launchOrigin, midApex, impactPos);\n\n// Dotted Trajectory Guide Line\nconst curvePoints = missileCurve.getPoints(80);\nconst trajGeo = new THREE.BufferGeometry().setFromPoints(curvePoints);\nconst trajMat = new THREE.LineDashedMaterial({\n  color: 0x58a6ff,\n  dashSize: 3,\n  gapSize: 2,\n  transparent: true,\n  opacity: 0.55\n});\nconst trajLine = new THREE.Line(trajGeo, trajMat);\ntrajLine.computeLineDistances();\nscene.add(trajLine);\n\n// 3D Missile Mesh\nconst missileGroup = new THREE.Group();\nconst bodyMesh = new THREE.Mesh(\n  new THREE.CylinderGeometry(0.65, 0.85, 7.5, 16),\n  new THREE.MeshStandardMaterial({ color: 0xe6edf3, metalness: 0.6, roughness: 0.3 })\n);\nbodyMesh.rotation.x = Math.PI / 2;\nconst noseMesh = new THREE.Mesh(\n  new THREE.ConeGeometry(0.65, 2.6, 16),\n  new THREE.MeshStandardMaterial({ color: 0xff3b30, metalness: 0.4, roughness: 0.3 })\n);\nnoseMesh.rotation.x = Math.PI / 2;\nnoseMesh.position.z = 5.05;\n\n// Rocket Exhaust Flame Cone\nconst flameMesh = new THREE.Mesh(\n  new THREE.ConeGeometry(1.1, 7.0, 16),\n  new THREE.MeshBasicMaterial({ color: 0xffaa22, transparent: true, opacity: 0.9 })\n);\nflameMesh.rotation.x = -Math.PI / 2;\nflameMesh.position.z = -7.0;\n\nmissileGroup.add(bodyMesh, noseMesh, flameMesh);\nmissileGroup.position.copy(launchOrigin);\nscene.add(missileGroup);\n\n// Missile Smoke Trail Particles\nconst TRAIL_COUNT = 120;\nconst trailGeo = new THREE.BufferGeometry();\nconst trailPositions = new Float32Array(TRAIL_COUNT * 3);\ntrailGeo.setAttribute(\"position\", new THREE.BufferAttribute(trailPositions, 3));\nconst trailMat = new THREE.PointsMaterial({\n  color: 0xffcfa3,\n  size: 2.8,\n  transparent: true,\n  opacity: 0.65\n});\nconst trailPoints = new THREE.Points(trailGeo, trailMat);\ntrailPoints.visible = false;\nscene.add(trailPoints);\n\n// =========================================================\n// 7. NUCLEAR EXPLOSION 3D FX (FIREBALL, SHOCKWAVE, MUSHROOM CLOUD, ZONES)\n// =========================================================\nconst explosionGroup = new THREE.Group();\nscene.add(explosionGroup);\n\n// 7A. Glowing Fireball Core + Outer Plasma Shell\nconst fireballCore = new THREE.Mesh(\n  new THREE.SphereGeometry(1, 32, 24),\n  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.95 })\n);\nconst fireballOuter = new THREE.Mesh(\n  new THREE.SphereGeometry(1.15, 32, 24),\n  new THREE.MeshBasicMaterial({ color: 0xff5500, transparent: true, opacity: 0.65 })\n);\nfireballCore.visible = false;\nfireballOuter.visible = false;\nexplosionGroup.add(fireballCore, fireballOuter);\n\n// 7B. Supersonic Shockwave Ring & Condensation Dome\nconst shockRing = new THREE.Mesh(\n  new THREE.RingGeometry(0.92, 1.0, 64),\n  new THREE.MeshBasicMaterial({ color: 0xdbeeff, side: THREE.DoubleSide, transparent: true, opacity: 0.75 })\n);\nshockRing.rotation.x = -Math.PI / 2;\nshockRing.position.y = 0.45;\nshockRing.visible = false;\n\nconst condDome = new THREE.Mesh(\n  new THREE.SphereGeometry(1, 32, 20, 0, Math.PI * 2, 0, Math.PI * 0.5),\n  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.22, wireframe: false, side: THREE.DoubleSide })\n);\ncondDome.visible = false;\nexplosionGroup.add(shockRing, condDome);\n\n// 7C. Ground Scorch Crater\nconst craterMesh = new THREE.Mesh(\n  new THREE.CircleGeometry(1, 48),\n  new THREE.MeshBasicMaterial({ color: 0x090707, transparent: true, opacity: 0.88 })\n);\ncraterMesh.rotation.x = -Math.PI / 2;\ncraterMesh.position.y = 0.15;\ncraterMesh.visible = false;\nexplosionGroup.add(craterMesh);\n\n// 7D. 4 Damage Zone Rings on Ground (Fireball, 20psi, 5psi, Thermal)\nfunction makeZoneRing(colorHex, yOffset) {\n  const mesh = new THREE.Mesh(\n    new THREE.RingGeometry(0.96, 1.0, 72),\n    new THREE.MeshBasicMaterial({ color: colorHex, side: THREE.DoubleSide, transparent: true, opacity: 0.85 })\n  );\n  mesh.rotation.x = -Math.PI / 2;\n  mesh.position.y = yOffset;\n  mesh.visible = false;\n  explosionGroup.add(mesh);\n  return mesh;\n}\nconst zoneFireballRing = makeZoneRing(0xff2a2a, 0.25);\nconst zone20Ring       = makeZoneRing(0xff6b00, 0.23);\nconst zone5Ring        = makeZoneRing(0xffd000, 0.21);\nconst zoneThermalRing  = makeZoneRing(0xff9e44, 0.19);\n\n// 7E. Radioactive Fallout Plume Polygon\nconst falloutShape = new THREE.Shape();\nfor (let i = 0; i <= 60; i++) {\n  const a = (i / 60) * Math.PI * 2;\n  const r = Math.pow(Math.cos(a / 2), 4);\n  const px = r * Math.sin(a);\n  const py = r * Math.cos(a);\n  if (i === 0) falloutShape.moveTo(px, py);\n  else falloutShape.lineTo(px, py);\n}\nconst falloutGeo = new THREE.ShapeGeometry(falloutShape);\nconst falloutMesh = new THREE.Mesh(\n  falloutGeo,\n  new THREE.MeshBasicMaterial({ color: 0xb44cff, transparent: true, opacity: 0.34, side: THREE.DoubleSide })\n);\nfalloutMesh.rotation.x = -Math.PI / 2;\nfalloutMesh.position.y = 0.18;\nfalloutMesh.visible = false;\nexplosionGroup.add(falloutMesh);\n\n// 7F. Volumetric-Style 3D Mushroom Cloud (Stem + Rolling Torus Cap)\nconst CLOUD_PUFFS = 220;\nconst puffGeo = new THREE.DodecahedronGeometry(1, 1);\nconst puffMat = new THREE.MeshStandardMaterial({\n  color: 0xffffff,\n  roughness: 0.92,\n  metalness: 0.05,\n  transparent: true,\n  opacity: 0.92\n});\nconst mushroomInstanced = new THREE.InstancedMesh(puffGeo, puffMat, CLOUD_PUFFS);\nmushroomInstanced.visible = false;\nexplosionGroup.add(mushroomInstanced);\n\nconst puffSeeds = [];\nfor (let i = 0; i < CLOUD_PUFFS; i++) {\n  puffSeeds.push({\n    isStem: i < 75,\n    angle: Math.random() * Math.PI * 2,\n    t: Math.random(),\n    speed: 0.6 + Math.random() * 0.8,\n    radiusJitter: 0.7 + Math.random() * 0.6,\n    scaleJitter: 0.75 + Math.random() * 0.65\n  });\n}\n\n// =========================================================\n// 8. PHYSICS CALCULATION & UI SYNC\n// =========================================================\nfunction getBlastMetrics() {\n  const y = state.yieldKt;\n  const airFactor = state.burstType === \"air\" ? 1.3 : 1.0;\n\n  const rFireballKm = 0.15 * Math.pow(y, 0.32);\n  const r20PsiKm    = 0.28 * Math.pow(y, 0.33) * airFactor;\n  const r5PsiKm     = 0.70 * Math.pow(y, 0.33) * airFactor;\n  const rThermalKm  = 1.20 * Math.pow(y, 0.40);\n  const falloutKm   = (state.burstType === \"ground\" && state.windSpeed > 0)\n    ? Math.pow(y, 0.45) * Math.pow(state.windSpeed, 0.5) * 0.95\n    : 0;\n\n  // Realistic capped metropolitan casualty model\n  const city = CITIES[state.cityKey];\n  const a20 = Math.PI * r20PsiKm * r20PsiKm;\n  const a5  = Math.max(0, Math.PI * r5PsiKm * r5PsiKm - a20);\n  const aTh = Math.max(0, Math.PI * rThermalKm * rThermalKm - (a20 + a5));\n\n  // Suburban density decays with distance\n  const rawDead = (a20 * city.density * 0.92) + (a5 * city.density * 0.35 * 0.65) + (aTh * city.density * 0.04 * 0.4);\n  const rawInj  = (a20 * city.density * 0.06) + (a5 * city.density * 0.45 * 0.65) + (aTh * city.density * 0.32 * 0.4);\n\n  const maxDead = Math.min(city.popCap * 0.68, Math.round(rawDead));\n  const maxInj  = Math.min(city.popCap * 0.30, Math.round(rawInj));\n\n  return {\n    rFireballKm, r20PsiKm, r5PsiKm, rThermalKm, falloutKm,\n    // Convert km to scene units (1 unit = 100m = 0.1km -> multiply km by 10)\n    uFireball: rFireballKm * 10,\n    u20Psi: r20PsiKm * 10,\n    u5Psi: r5PsiKm * 10,\n    uThermal: rThermalKm * 10,\n    uFallout: falloutKm * 10,\n    maxDead, maxInj\n  };\n}\n\nfunction updateStaticReadouts() {\n  const m = getBlastMetrics();\n  document.getElementById(\"yield-badge\").textContent = `${state.yieldKt.toLocaleString()} kt`;\n  document.getElementById(\"wind-deg-badge\").textContent = `${state.windDeg}\u00b0`;\n  document.getElementById(\"wind-spd-badge\").textContent = `${state.windSpeed} km/h`;\n\n  document.getElementById(\"rad-fireball\").textContent = `${m.rFireballKm.toFixed(2)} km`;\n  document.getElementById(\"rad-20psi\").textContent    = `${m.r20PsiKm.toFixed(2)} km`;\n  document.getElementById(\"rad-5psi\").textContent     = `${m.r5PsiKm.toFixed(2)} km`;\n  document.getElementById(\"rad-thermal\").textContent  = `${m.rThermalKm.toFixed(2)} km`;\n  document.getElementById(\"rad-fallout\").textContent  = m.falloutKm > 0 ? `${m.falloutKm.toFixed(1)} km` : \"\ucd5c\uc18c\ud654 (\uacf5\uc911\ud3ed\ubc1c)\";\n}\n\n// =========================================================\n// 9. FRAME-BY-FRAME ANIMATION UPDATE\n// =========================================================\nconst puffColor = new THREE.Color();\nconst flashOverlay = document.getElementById(\"flash-overlay\");\n\nfunction renderSimulationState(p) {\n  const m = getBlastMetrics();\n  const elapsedSec = p * state.totalDuration;\n  document.getElementById(\"hud-time\").textContent = `T+ ${elapsedSec.toFixed(1)}s`;\n  document.getElementById(\"timeline-slider\").value = Math.round(p * 1000);\n\n  const statusEl = document.getElementById(\"hud-status\");\n\n  // -------------------------------------------------------\n  // PHASE A: MISSILE FLIGHT (0.0 <= p < impactPoint)\n  // -------------------------------------------------------\n  if (p < state.impactPoint) {\n    state.flashTriggered = false;\n    flashOverlay.style.opacity = 0;\n    blastLight.intensity = 0;\n\n    // Hide explosion meshes\n    fireballCore.visible = false;\n    fireballOuter.visible = false;\n    shockRing.visible = false;\n    condDome.visible = false;\n    craterMesh.visible = false;\n    mushroomInstanced.visible = false;\n    zoneFireballRing.visible = false;\n    zone20Ring.visible = false;\n    zone5Ring.visible = false;\n    zoneThermalRing.visible = false;\n    falloutMesh.visible = false;\n    updateCityDestruction(0);\n\n    document.getElementById(\"stat-dead\").textContent = \"0 \uba85\";\n    document.getElementById(\"stat-injured\").textContent = \"0 \uba85\";\n    document.getElementById(\"hud-cloud\").textContent = \"0.0 km\";\n\n    const flightT = p / state.impactPoint; // 0 -> 1\n    missileGroup.visible = true;\n    trajLine.visible = true;\n\n    const pos = missileCurve.getPoint(flightT);\n    const nextPos = missileCurve.getPoint(Math.min(1, flightT + 0.01));\n    missileGroup.position.copy(pos);\n    missileGroup.lookAt(nextPos);\n\n    // Exhaust flame flicker\n    const flicker = 0.85 + Math.random() * 0.45;\n    flameMesh.scale.set(1, flicker, 1);\n\n    // Update smoke trail\n    if (p > 0.002) {\n      statusEl.textContent = \"\ud0c4\ub3c4 \ube44\ud589 \uc911\";\n      statusEl.className = \"tele-val status-flight\";\n      trailPoints.visible = true;\n      for (let i = 0; i < TRAIL_COUNT; i++) {\n        const sampleT = Math.max(0, flightT - (i / TRAIL_COUNT) * 0.35);\n        const pt = missileCurve.getPoint(sampleT);\n        trailPositions[i * 3]     = pt.x + (Math.random() - 0.5) * 0.6;\n        trailPositions[i * 3 + 1] = pt.y + (Math.random() - 0.5) * 0.6;\n        trailPositions[i * 3 + 2] = pt.z + (Math.random() - 0.5) * 0.6;\n      }\n      trailGeo.attributes.position.needsUpdate = true;\n    } else {\n      statusEl.textContent = \"\ubc1c\uc0ac \ub300\uae30\";\n      statusEl.className = \"tele-val status-ready\";\n      trailPoints.visible = false;\n    }\n\n    const altKm = pos.y * 0.1;\n    const mach = p > 0 ? (6.5 + flightT * 11.5) : 0;\n    document.getElementById(\"hud-alt\").textContent = `${altKm.toFixed(1)} km`;\n    document.getElementById(\"hud-speed\").textContent = `Mach ${mach.toFixed(1)}`;\n\n    // Camera Director during flight\n    if (state.cameraMode === \"missile\" || (state.cameraMode === \"auto\" && p > 0.002 && flightT < 0.82)) {\n      const camOffset = new THREE.Vector3(-18, 12, -16);\n      camera.position.lerp(pos.clone().add(camOffset), 0.14);\n      controls.target.lerp(pos, 0.2);\n    } else if (state.cameraMode === \"auto\" && flightT >= 0.82) {\n      // Pull back to dramatic impact overview right before strike\n      const viewDist = Math.max(85, m.u5Psi * 2.2);\n      camera.position.lerp(new THREE.Vector3(0, viewDist * 0.65, viewDist * 1.15), 0.12);\n      controls.target.lerp(new THREE.Vector3(0, 12, 0), 0.15);\n    } else if (state.cameraMode === \"ground\") {\n      camera.position.set(18, 3.2, 22);\n      controls.target.lerp(pos, 0.25);\n    }\n    return;\n  }\n\n  // -------------------------------------------------------\n  // PHASE B: DETONATION & MUSHROOM CLOUD (impactPoint <= p <= 1.0)\n  // -------------------------------------------------------\n  missileGroup.visible = false;\n  trailPoints.visible = false;\n  trajLine.visible = false;\n\n  statusEl.textContent = \"\ud575\ud3ed\ubc1c \ubc1c\uc0dd!\";\n  statusEl.className = \"tele-val status-detonated\";\n  document.getElementById(\"hud-alt\").textContent = state.burstType === \"air\" ? \"0.6 km (\uacf5\uc911)\" : \"0.0 km (\ud0c4\ucc29)\";\n  document.getElementById(\"hud-speed\").textContent = \"DETONATED\";\n\n  if (!state.flashTriggered && state.phase === \"playing\") {\n    state.flashTriggered = true;\n    playExplosionSound();\n  }\n\n  const postT = (p - state.impactPoint) / (1.0 - state.impactPoint); // 0 -> 1\n\n  // 1. Thermal Blinding Flash (fast decay in first 12% of post-impact)\n  const flashVal = Math.max(0, 1 - postT / 0.12);\n  flashOverlay.style.opacity = (flashVal * flashVal * 0.92).toFixed(3);\n  blastLight.intensity = flashVal * 18 + Math.max(0, 1 - postT * 1.4) * 5;\n\n  // 2. Fireball Expansion & Cooling\n  const fbGrow = Math.min(1, postT / 0.18);\n  const fbRadius = Math.max(1.5, m.uFireball * (0.25 + 0.75 * Math.pow(fbGrow, 0.55)));\n  const fbHeight = state.burstType === \"air\" ? fbRadius * 0.85 : fbRadius * 0.35;\n\n  fireballCore.visible = postT < 0.55;\n  fireballOuter.visible = postT < 0.75;\n  fireballCore.position.set(0, fbHeight + postT * 18, 0);\n  fireballOuter.position.copy(fireballCore.position);\n\n  const coreScale = fbRadius * Math.max(0.1, 1 - postT * 1.3);\n  fireballCore.scale.set(coreScale, coreScale, coreScale);\n  fireballOuter.scale.set(fbRadius, fbRadius, fbRadius);\n  fireballOuter.material.opacity = Math.max(0, 0.72 * (1 - postT / 0.75));\n\n  // 3. Supersonic Shockwave Ring & Condensation Dome\n  const shockExpand = Math.min(1.25, postT / 0.45);\n  const currentShockR = m.uThermal * shockExpand;\n  shockRing.visible = postT < 0.55;\n  shockRing.scale.set(Math.max(1, currentShockR), Math.max(1, currentShockR), 1);\n  shockRing.material.opacity = Math.max(0, 0.85 * (1 - postT / 0.55));\n\n  condDome.visible = postT < 0.32;\n  const domeR = m.u5Psi * (postT / 0.32) * 1.3;\n  condDome.scale.set(Math.max(1, domeR), Math.max(1, domeR * 0.75), Math.max(1, domeR));\n  condDome.material.opacity = Math.max(0, 0.28 * (1 - postT / 0.32));\n\n  // Destroy 3D city buildings dynamically as the shockwave sweeps past them!\n  updateCityDestruction(currentShockR, m.uFireball, m.u20Psi, m.u5Psi);\n\n  // 4. Crater & Ground Damage Zone Rings\n  craterMesh.visible = true;\n  const cRad = Math.max(1.2, m.uFireball * 0.85);\n  craterMesh.scale.set(cRad, cRad, 1);\n\n  zoneFireballRing.visible = true;\n  zone20Ring.visible = true;\n  zone5Ring.visible = true;\n  zoneThermalRing.visible = true;\n\n  const zProg = Math.min(1, postT / 0.35);\n  zoneFireballRing.scale.set(Math.max(0.1, m.uFireball * zProg), Math.max(0.1, m.uFireball * zProg), 1);\n  zone20Ring.scale.set(Math.max(0.1, m.u20Psi * zProg), Math.max(0.1, m.u20Psi * zProg), 1);\n  zone5Ring.scale.set(Math.max(0.1, m.u5Psi * zProg), Math.max(0.1, m.u5Psi * zProg), 1);\n  zoneThermalRing.scale.set(Math.max(0.1, m.uThermal * zProg), Math.max(0.1, m.uThermal * zProg), 1);\n\n  // 5. Fallout Plume Growth\n  if (m.uFallout > 0 && postT > 0.12) {\n    falloutMesh.visible = true;\n    const fProg = Math.min(1, (postT - 0.12) / 0.88);\n    const fLen = Math.max(2, m.uFallout * fProg);\n    const fWid = fLen * 0.28;\n    falloutMesh.scale.set(fWid, fLen, 1);\n    // Align wind direction (0 deg = North -> South, 90 deg = West -> East)\n    falloutMesh.rotation.z = -THREE.MathUtils.degToRad(state.windDeg);\n  } else {\n    falloutMesh.visible = false;\n  }\n\n  // 6. Towering 3D Mushroom Cloud (Stem + Rolling Toroidal Cap)\n  mushroomInstanced.visible = true;\n  const cloudMaxH = Math.min(155, Math.max(24, m.uFireball * 4.5));\n  const cloudCapR = Math.min(95, Math.max(11, m.uFireball * 2.1));\n  const riseProgress = Math.pow(postT, 0.62);\n  const currentCloudTop = cloudMaxH * riseProgress;\n  document.getElementById(\"hud-cloud\").textContent = `${(currentCloudTop * 0.1).toFixed(1)} km`;\n\n  // Wind drift offset at high altitude\n  const windRad = THREE.MathUtils.degToRad(state.windDeg);\n  const driftTotal = (state.windSpeed * 0.22) * postT;\n  const driftX = Math.sin(windRad) * driftTotal;\n  const driftZ = -Math.cos(windRad) * driftTotal;\n\n  for (let i = 0; i < CLOUD_PUFFS; i++) {\n    const s = puffSeeds[i];\n    if (s.isStem) {\n      // Rising central column with base suction flare\n      const hNorm = (s.t + postT * 0.45 * s.speed) % 1.0;\n      const y = hNorm * currentCloudTop * 0.82;\n      const flare = hNorm < 0.2 ? (1.8 - hNorm * 4) : 1.0;\n      const stemR = cloudCapR * 0.22 * flare * s.radiusJitter;\n      const theta = s.angle + postT * 2.2 * s.speed;\n\n      dummy.position.set(\n        Math.cos(theta) * stemR + driftX * hNorm,\n        y + 1.2,\n        Math.sin(theta) * stemR + driftZ * hNorm\n      );\n      const pScale = cloudCapR * 0.24 * s.scaleJitter * Math.min(1, postT * 4);\n      dummy.scale.set(pScale, pScale * 0.85, pScale);\n\n      // Hot glowing core early on, cooling to dark ash smoke\n      const heat = Math.max(0, 1 - postT * 1.45) * (1 - hNorm * 0.4);\n      puffColor.setRGB(\n        0.26 + heat * 0.74,\n        0.24 + heat * 0.34,\n        0.25 + heat * 0.05\n      );\n    } else {\n      // Rolling Mushroom Cap (Torus Vortex)\n      const torusAngle = s.angle + postT * 1.1;\n      const rollPhase = (s.t * Math.PI * 2) + postT * 4.5 * s.speed;\n      const majorR = cloudCapR * (0.58 + 0.32 * riseProgress) * s.radiusJitter;\n      const minorR = cloudCapR * (0.32 + 0.16 * riseProgress);\n\n      const radial = majorR + Math.cos(rollPhase) * minorR;\n      const yOffset = Math.sin(rollPhase) * minorR * 0.72;\n\n      dummy.position.set(\n        Math.cos(torusAngle) * radial + driftX,\n        currentCloudTop * 0.84 + yOffset,\n        Math.sin(torusAngle) * radial + driftZ\n      );\n      const capScale = cloudCapR * 0.36 * s.scaleJitter * Math.min(1, postT * 3.5);\n      dummy.scale.set(capScale, capScale * 0.78, capScale);\n\n      // Inner underside glows fiery orange; top outer cloud is bright sunlit smoke\n      const underGlow = Math.max(0, -Math.sin(rollPhase)) * Math.max(0, 1 - postT * 1.35);\n      const topHighlight = Math.max(0, Math.sin(rollPhase)) * 0.38;\n      puffColor.setRGB(\n        Math.min(1, 0.48 + topHighlight + underGlow * 0.52),\n        Math.min(1, 0.45 + topHighlight + underGlow * 0.22),\n        Math.min(1, 0.46 + topHighlight)\n      );\n    }\n\n    dummy.rotation.set(s.angle, postT, s.t);\n    dummy.updateMatrix();\n    mushroomInstanced.setMatrixAt(i, dummy.matrix);\n    mushroomInstanced.setColorAt(i, puffColor);\n  }\n  mushroomInstanced.instanceMatrix.needsUpdate = true;\n  if (mushroomInstanced.instanceColor) mushroomInstanced.instanceColor.needsUpdate = true;\n\n  // 7. Live Casualty Counter Progression\n  const casProg = Math.min(1, postT / 0.55);\n  const curDead = Math.round(m.maxDead * casProg);\n  const curInj  = Math.round(m.maxInj * casProg);\n  document.getElementById(\"stat-dead\").textContent = `${curDead.toLocaleString()} \uba85`;\n  document.getElementById(\"stat-injured\").textContent = `${curInj.toLocaleString()} \uba85`;\n\n  // 8. Camera Shake & Auto Director Pullback\n  if (state.cameraMode === \"auto\") {\n    const targetDist = Math.max(95, Math.min(460, m.u5Psi * 2.4 + currentCloudTop * 1.3));\n    const desiredCam = new THREE.Vector3(targetDist * 0.45, targetDist * 0.55, targetDist * 1.05);\n    camera.position.lerp(desiredCam, 0.045);\n    controls.target.lerp(new THREE.Vector3(0, currentCloudTop * 0.35, 0), 0.06);\n  } else if (state.cameraMode === \"ground\") {\n    camera.position.set(22, 3.2, 26);\n    controls.target.lerp(new THREE.Vector3(0, currentCloudTop * 0.48, 0), 0.08);\n  }\n\n  // Camera shake right at detonation\n  if (postT < 0.08 && state.phase === \"playing\") {\n    const shake = (1 - postT / 0.08) * 2.2;\n    camera.position.x += (Math.random() - 0.5) * shake;\n    camera.position.y += (Math.random() - 0.5) * shake;\n  }\n}\n\n// =========================================================\n// 10. UI EVENT LISTENERS\n// =========================================================\ndocument.getElementById(\"target-select\").addEventListener(\"change\", (e) => {\n  state.cityKey = e.target.value;\n  loadRealMapTiles();\n  generateCityBuildings();\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"weapon-select\").addEventListener(\"change\", (e) => {\n  if (e.target.value !== \"custom\") {\n    state.yieldKt = parseFloat(e.target.value);\n    document.getElementById(\"yield-slider\").value = yieldToSlider(state.yieldKt);\n  }\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"yield-slider\").addEventListener(\"input\", (e) => {\n  state.yieldKt = sliderToYield(parseInt(e.target.value, 10));\n  document.getElementById(\"weapon-select\").value = \"custom\";\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"btn-ground\").addEventListener(\"click\", () => {\n  state.burstType = \"ground\";\n  document.getElementById(\"btn-ground\").classList.add(\"active\");\n  document.getElementById(\"btn-air\").classList.remove(\"active\");\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"btn-air\").addEventListener(\"click\", () => {\n  state.burstType = \"air\";\n  document.getElementById(\"btn-air\").classList.add(\"active\");\n  document.getElementById(\"btn-ground\").classList.remove(\"active\");\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"btn-map-dark\").addEventListener(\"click\", () => {\n  state.mapStyle = \"dark\";\n  document.getElementById(\"btn-map-dark\").classList.add(\"active\");\n  document.getElementById(\"btn-map-sat\").classList.remove(\"active\");\n  loadRealMapTiles();\n});\n\ndocument.getElementById(\"btn-map-sat\").addEventListener(\"click\", () => {\n  state.mapStyle = \"sat\";\n  document.getElementById(\"btn-map-sat\").classList.add(\"active\");\n  document.getElementById(\"btn-map-dark\").classList.remove(\"active\");\n  loadRealMapTiles();\n});\n\ndocument.getElementById(\"wind-deg\").addEventListener(\"input\", (e) => {\n  state.windDeg = parseInt(e.target.value, 10);\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"wind-spd\").addEventListener(\"input\", (e) => {\n  state.windSpeed = parseInt(e.target.value, 10);\n  updateStaticReadouts();\n  renderSimulationState(state.progress);\n});\n\ndocument.getElementById(\"launch-btn\").addEventListener(\"click\", () => {\n  state.progress = 0.003;\n  state.phase = \"playing\";\n  state.flashTriggered = false;\n  document.getElementById(\"pause-btn\").textContent = \"\u23f8 \uc77c\uc2dc\uc815\uc9c0\";\n  playLaunchSound();\n});\n\ndocument.getElementById(\"pause-btn\").addEventListener(\"click\", () => {\n  if (state.phase === \"playing\") {\n    state.phase = \"paused\";\n    document.getElementById(\"pause-btn\").textContent = \"\u25b6 \uacc4\uc18d\uc7ac\uc0dd\";\n  } else if (state.phase === \"paused\") {\n    state.phase = \"playing\";\n    document.getElementById(\"pause-btn\").textContent = \"\u23f8 \uc77c\uc2dc\uc815\uc9c0\";\n  }\n});\n\ndocument.getElementById(\"reset-btn\").addEventListener(\"click\", () => {\n  state.phase = \"ready\";\n  state.progress = 0.0;\n  state.flashTriggered = false;\n  document.getElementById(\"pause-btn\").textContent = \"\u23f8 \uc77c\uc2dc\uc815\uc9c0\";\n  camera.position.set(0, 145, 220);\n  controls.target.set(0, 10, 0);\n  renderSimulationState(0);\n});\n\ndocument.getElementById(\"sound-btn\").addEventListener(\"click\", (e) => {\n  state.soundEnabled = !state.soundEnabled;\n  e.target.textContent = state.soundEnabled ? \"\ud83d\udd0a \ud6a8\uacfc\uc74c ON\" : \"\ud83d\udd07 \ud6a8\uacfc\uc74c OFF\";\n});\n\ndocument.getElementById(\"timeline-slider\").addEventListener(\"input\", (e) => {\n  state.phase = \"paused\";\n  document.getElementById(\"pause-btn\").textContent = \"\u25b6 \uacc4\uc18d\uc7ac\uc0dd\";\n  state.progress = parseInt(e.target.value, 10) / 1000;\n  renderSimulationState(state.progress);\n});\n\ndocument.querySelectorAll(\".cam-pill\").forEach(pill => {\n  pill.addEventListener(\"click\", () => {\n    document.querySelectorAll(\".cam-pill\").forEach(p => p.classList.remove(\"active\"));\n    pill.classList.add(\"active\");\n    state.cameraMode = pill.getAttribute(\"data-cam\");\n  });\n});\n\nwindow.addEventListener(\"resize\", () => {\n  camera.aspect = window.innerWidth / window.innerHeight;\n  camera.updateProjectionMatrix();\n  renderer.setSize(window.innerWidth, window.innerHeight);\n});\n\n// =========================================================\n// 11. MAIN 60FPS RENDER LOOP\n// =========================================================\nlet lastTime = performance.now();\nfunction animate(now) {\n  requestAnimationFrame(animate);\n  const dt = Math.min(0.05, (now - lastTime) / 1000);\n  lastTime = now;\n\n  // Pulse target reticle\n  const pulse = 1 + Math.sin(now * 0.005) * 0.14;\n  retRing1.scale.set(pulse, pulse, 1);\n\n  if (state.phase === \"playing\") {\n    state.progress += dt / state.totalDuration;\n    if (state.progress >= 1.0) {\n      state.progress = 1.0;\n      state.phase = \"finished\";\n    }\n    renderSimulationState(state.progress);\n  }\n\n  controls.update();\n  renderer.render(scene, camera);\n}\n\n// Boot\nloadRealMapTiles();\ngenerateCityBuildings();\nupdateStaticReadouts();\nrenderSimulationState(0);\nrequestAnimationFrame(animate);\n</script>\n</body>\n</html>\n"

